struct node
{
    int data;
    struct node *next;
}*first;

void create(int A[], int n)
{
    struct node *t, *last;
    first = (struct node*)malloc(sizeof(struct node));
    first->data = A[0];
    first->next = NULL;
    last = first;

    for(int i = 1 ; i < n ; i++)
    {
        t = (struct node*)malloc(sizeof(struct node));
        t->data = A[i];
        t->next = NULL;
        last->next = t;
        last = t;
    }
}

void display(struct node *p)
{
    while(p)
    {
        printf("%d ", p->data);
        p = p->next;
    }
    printf("\n");
}

void reverse_m(struct node *p, int m)
{
    int counter = 0;
    struct node *q = NULL;
    struct node *r = NULL;


    while(counter < m)
    {
        r = q;
        q = p;
        p = p->next;
        q->next = r;
        counter++;
    }
    first = q;




    while(q->next != NULL)
    {
        q = q->next;
    }
    q->next = p;
}

