        r = random();
        setInt(&r1, r);
        for (j = 0; j < 10;j++){
            mulBy10(&r1, &tmp);
            copyNumber(&tmp, &r1);
        }
        sqrt_newton(&r1, &ans);
        printf("r1:");
        dispNumberZeroSuppress(&ans);
        puts("");
        r2 = sqrt((double)r);
        printf("r2:%f\n", r2);
