#define inf 9999
void matrix_chain_multiplication(int p[11],int n,int M[11][11],int S[11][11])
{
 int i,j,k,l,q;
 for(l=2;l<=n;l++)
 {
  for(i=1;i<=n-l+1;i++)
  {
   j=i+l-1;
   M[i][j]=inf;
   for(k=i;k<=j-1;k++)
   {
    q=M[i][k]+M[k+1][j]+p[i-1]*p[k]*p[j];
    if(q<M[i][j])
    {
     M[i][j]=q;
     S[i][j]=k;
    }
   }
  }
 }
}

void putdata(int A[11][11],int row,int column)
{
 int i,j;
 for(i=1;i<=row;i++)
 {
   for(j=1;j<=column;j++)
   {
    printf("%d\t",A[i][j]);
   }
   printf("\n");
 }
}
