     void getdata(int x[50],int n)
       {
        int k;
        printf("enter the value  for sorting\n");
        for(k=0;k<n;k++)
        {
         scanf("%d",&x[k]);
        }     
       }
     void putdata(int x[50], int n)
       {
        int k;
