    int partition(int a[50],int p,int r)
   {
    int x,i,j,temp;
    x=a[r];
    i=p-1;
    count++;
    for(j=p;j<=r-1;j++)
    {
        count++;
        if(a[j]<=x)
        {
        count++;
            i=i+1;
        count++;
            temp=a[j];
        count++;
            a[j]=a[i];
        count++;
            a[i]=temp;
        count++;
        }
        count++;
    }
    count++;
    temp =a[r];
    count++;
    a[r]=a[i+1];                       
    count++;
    a[i+1]=temp;
    count++;
    return i+1;
    }

void quick_sort(int a[50],int p,int r)
{   
    int q;
    count++;
    if(p<r)
    {
        count++;
        q=partition(a,p,r);
        count++;
        quick_sort(a,p,q-1);
        count++;
        quick_sort(a,q+1,r);
        count++;
    }
}
