int check_digit(int n)
{
    int count=0;
    if(n==0)
        return 1;
    while(n>0)
    {
        n=n/10;
        count++;
    }
    return count;
}
int check_digit_array(int A[], int n)
{
    int s;
    int num = check_digit(A[0]);
    for(int i = 1; i<n; i++)
    {
        s = check_digit(A[i]);
        if(s != num)
            return 0;
    }
    return 1;
}


int getMax(int arr[], int n) {
    int mx = arr[0];
    int i;
    for (i = 1; i < n; i++)
        if (arr[i] > mx)
            mx = arr[i];
    return mx;
}

void countSort(int arr[], int n, int exp) {
    int output[n]; 
    int i, count[10] = { 0 };
    for (i = 0; i < n; i++)
        count[(arr[i] / exp) % 10]++;

    for (i = 1; i < 10; i++)
        count[i] += count[i - 1];

    for (i = n - 1; i >= 0; i--) {
        output[count[(arr[i] / exp) % 10] - 1] = arr[i];
        count[(arr[i] / exp) % 10]--;
    }

    for (i = 0; i < n; i++)
        arr[i] = output[i];
}

void radix_sort(int arr[], int n) {
    int m = getMax(arr, n);

    int exp;
    for (exp = 1; m / exp > 0; exp *= 10)
        countSort(arr, n, exp);
}

