}


void display(int array[MAX], int length)
{
    int i = 0;
    for(i=0; i<length; i++)
        printf("%d\t", array[i]);

    printf("\n");
}


void insertion_sort(int array[MAX], int length)
{
    int i, j, temp = 0;
    int size = length;

    for(i=1; i<size; i++)
    {
        j = i;
        while((array[j] < array[j-1]) && j>0)
        {

            temp = array[j];
            array[j] = array[j-1];
            array[j-1] = temp;
            j--;
        }
    }
