double power(double x, int y){
    double result = x;
    if(x == 0) return 0;
    if(y == 0) return 1;
    if(y<0){
        result = 1/x;
       for(int i = y + 1; i < 0; i++){
        result = result * (1/x);
        }
        return result;
    }
    for(int i = 1; i < y; i++){
        result = result * x;
    }
    return result;
}
