void changeCells(unsigned int n, int * array1, int * array2, int * array3){
    int i = 0;
    for(i; i < n; i++){
        int a = array1[i], b = array2[i], c = array3[i];
        int max = (a>=b && a>=c) ? a : (b>=a&&b>=c) ? b : c;
        int min = (a<=b && a<=c) ? a : (b<=a&&b<=c) ? b : c;
        int mid = (c!=max && c!=min) ? c : (b!=max && b!=min) ? b : a;
        array1[i] = max;
        array2[i] = mid;
        array3[i] = min;
    }
};
