double fatorial (int i)
{
    double res = 1;
    for (int j=1; j<i; j++)
    {
        res = res*(j+1);
    }
    return res;
}

double potencia (double x, int i)
{
    double x0 = 1;
    for (int j=0; j<i; j++)
    {
        x0 *= x;
    }

    return x0;
}

