    seno = x;

    for (int i=3,j=1; j<=iteracoes; i=i+2,j++)
    {
        if ((j%2) == 0)
        {
            seno += potencia(x,i)/fatorial(i);
        }
        else
        {
            seno -= potencia(x,i)/fatorial(i);
        }    

    }

    printf ("%.10lf\n", seno);
    return 0;
