typedef enum Ordem
{
    normal,
    inversa

} ordem_t;

void imprime_elemento(long int *vet, long int i, long int n, ordem_t ordem)
{
    printf("%li ", *(vet + i));

    if (ordem == normal)
    {
        return (i < n-1) ? imprime_elemento(vet, i+1, n, ordem) : 0;
    }

    else if (ordem == inversa)
    {
        return (i > 0) ? imprime_elemento(vet, i-1, NULL, ordem) : 0;
    }
}


