        getchar();
        printf("\t-> n: ");
        scanf("%i", &n);
        getchar();
        system("clear");

    } while (n < 0 || m < 0);

    printf("\nA(%i,%i) = %li\n\n", m, n, ackermann(m,n));

    return 0;
