        fp=fopen("File18Final.txt","w");

        if(fptr==NULL||fp==NULL)
            {
                printf("\n Unable to open file");
                exit(1);
            }

        while((ch=fgetc(fptr))!=EOF)
            {
                if(isupper(ch))
                    ch=tolower(ch);
