                strcpy(s,p[i].name);
                strcpy(p[i].name,p[j].name);
                strcpy(p[j].name,s);
            }
        }
    }
    k=0;
    temp=0;
    while(k<n)
    {
        init_temp=temp;
        min=1000;
        printf("\nq");
        for(i=0;i<n;i++)
        {
            printf("\nw");
            if(p[i].BT1<min && p[i].BT1!=0 && p[i].AT<=temp)
            {
                min=p[i].BT1;
            }
        }
        for(i=0;i<n;i++)
        {
            printf("\ne");
            if(p[i].AT<=temp && p[i].status==0 && p[i].BT1<=min)
            {
                p[i].BT1--;
                temp++;
                p[i].CT=temp;
                break;
            }
        }
        for(i=0;i<n;i++)
        {
            printf("\nr");
            if(p[i].BT1==0 && p[i].status==0)
            {
                k=k+1;
                p[i].status=k;
            }
        }
        if(init_temp==temp)
            temp++;
    }
    printf("\nstatus : ");
    for(i=0;i<n;i++)
        printf("\t%d",p[i].status);
    printf("\nprocess\tAT\tBT\tCT\tTAT\tWT");
    k1=1;
    while(k1<=k)
    {
        for(i=0;i<n;i++)
        {
            if(p[i].status==k1)
            {
                p[i].TAT=p[i].CT-p[i].AT;
                p[i].WT=p[i].TAT-p[i].BT;
                sum=sum+p[i].WT;
                printf("\n%s\t%d\t%d\t%d\t%d\t%d",p[i].name,p[i].AT,p[i].BT,p[i].CT,p[i].TAT,p[i].WT);
                k1++;
            }
        }
    }
    Waiting_time=(sum*1.0)/n;
    printf("\nAverage Waiting_time : %f",Waiting_time);
