                printf("\nEnter file name : ");
                scanf("%s",name);
                add_file(name[0]);
                break;
            }
            case 2: 
            {
                printf("\nEnter file name : ");
                scanf("%s",name);
                rem_file(name[0]);
                break;
            }
            case 3:
            {
                display();
                break;
            }
            default:
            {
                exit(0);
                break;
            }
        }
    }
