                        }
                    }
                }
            }
            break;
        }
    }
    return captchaGerado;
}

logico validarCaptcha ( char captchaLido[6], char captchaGerado [6]) {
    int contador, contIguais;

    contIguais=0;
    for (contador=0; contador<6; contador++) {
        if( captchaLido[contador] == captchaGerado[contador]) {
            contIguais++;
        } else {
            contIguais = 0;
            break;
        }
    }

    if ( contIguais == 6) {
        return TRUE;
    } else {
        if(contIguais == 0) {
            return FALSE;
        }
    }
}

