int bfs(char*** maze,int*** d,int sr,int sc,int sh){

    int laststep=0;
    int arrive=0;
    element position;
    position.row = sr;
    position.col = sc;
    position.hei = sh;


    addq(position);
    int i,j,k,q;
    for(i=0;i<n/2+1;i++){
        for(j=0;j<n+2;j++){
            for(k=0;k<n+2;k++){
                d[i][j][k]=MAX;
            }
        }
    }
    d[sh][sr][sc]=0;


    int nr,nc,nh;
    int row,col,hei;
    while(rear!=front){



        position = deleteq();
        row = position.row;
        col = position.col;
        hei = position.hei;




        if(laststep!=d[hei][row][col] ){

            if(front2!=rear2){
                for(i=front2+1;i<=rear2;i++){
                    if(queue2[i].flag!=0){
                        if((queue2[i].flag-d[hei][row][col]+laststep)>=0){
                            queue2[i].flag-=(d[hei][row][col]-laststep);



                        }
                        else queue2[i].flag=0;
                    }
                    if(queue2[i].flag==0){
                        addq(queue2[i].t);
                        deleteq2();
                        nr = queue2[i].t.row;
                        nc = queue2[i].t.col;
                        nh = queue2[i].t.hei;

                        d[nh][nr][nc]=d[hei][row][col]+1;

                    }
                }
            }
            laststep=d[hei][row][col];
        }




        if(maze[hei][row][col]=='U' || maze[hei][row][col]=='D'){


            int upanddown=-1;
            if(maze[hei][row][col]=='U'){

                upanddown=1;
            }


            nr = row;
            nc = col;
            nh = hei+upanddown;


            if(nh>=0){
                if(maze[nh][nr][nc]=='F'){
                    d[nh][nr][nc]=d[hei][row][col]+1;


                    if(min>d[nh][nr][nc]){
                        min = d[nh][nr][nc];
                    }

                    return 1;
                }
                if(maze[nh][nr][nc]=='T'&& d[nh][nr][nc]==MAX){

                    d[nh][nr][nc]=-1;
                    element nextposition;
