typedef struct{
    short int vert;
    short int horiz;
}offsets;
offsets move[4];


int min=100000;

int bfs(char** maze,int **d,int num,int sx,int sy){
    int arrive=0;

    queue[0].row = sx; queue[0].col = sy;
    rear++;

    int i,j;
    for(i=0;i<num+2;i++){
        for(j=0;j<num+2;j++){
            d[i][j]=MAX;
        }
    }
    d[sx][sy]=0;


    element position;
    int nr,nc;
    int row,col;
    while (rear!=front){
        position = deleteq();
        row = position.row;
        col = position.col;

        if(maze[row][col]=='F'){
            if(min>d[row][col]){
                min=d[row][col];
            }
            arrive=1;
            break;
        }

        for(i=0;i<4;i++){
            nr = position.row+move[i].vert;
            nc = position.col+move[i].horiz;

            if (maze[nr][nc]!='X' && d[nr][nc]>d[row][col]+1){
                d[nr][nc]=d[row][col]+1;;
                element nextposition;
                nextposition.row=nr;nextposition.col=nc;
                addq(nextposition);
            }
        }

    }
    return arrive;
}

void path(int **d,char **maze,char** road,int fx,int fy,int num){
    int row=fx;
    int col=fy;
    int i,j,nr,nc;
    road[row][col]='*';
    while(maze[row][col]!='S'){
        for(i=0;i<4;i++){
            nr = row+move[i].vert;
            nc = col+move[i].horiz;
            if (d[nr][nc] == d[row][col]-1){

                row=nr;
                col=nc;
                break;
            }
        }
        road[row][col]='*';
    }
}

