    }
    rval=bind(sockid,(struct sockaddr*)&lis,sizeof(lis));
    if(rval==-1)
    {
        perror("BIND-ERR:");
        close(sockid);
        exit(1);
    }
    printf("\nThe Listener is ready to accept messages\n");
    tlen=sizeof(talk);
    while(1)
    {
        strncpy(msg," ",100);
        rval=recvfrom(sockid,msg,sizeof(msg),0,(struct sockaddr*)&talk,&tlen);
        if(rval==-1)
        {
            perror("MSG-RCV-ERR:");
            close(sockid);
            exit(1);
        }
        printf("\nMessage %d read is %s\n",++count,msg);
        if(!strcmp(msg,"EXIT"))
        break;
    }
    close(sockid);
}
