{
    int n;
    printf("Enter no. of elemnts: ");
    scanf("%d", &n);

    char str[SIZE];
    nptr list=createNode();

    for(int i = 0 ; i < n ; i++)
    {
        printf("Enter word to insert: "); 
        scanf("%s", str);
        insertf(list, str);
    }

    disp(list);
    rev(list);
    disp(list);
