typedef struct node
{
    int data;
    struct node* next;
}*NODE;
NODE insert(NODE first,int e,int pr)
{
    NODE temp=(NODE)malloc(sizeof(struct node));
    temp->data=e;
    temp->next=NULL;
    if (first==NULL)
        return temp;
    else if(first->next==NULL)
    {
        if (first->data>e)
        {
            temp->next=first;
            return temp;
        }
        else if(first->data<e)
            first->next=temp;
        else
        {
            if (pr==1)
                printf("Input not unique\n");
            free(temp);
        }
    }
    else
    {
        NODE m=first;
        while(m->next!=NULL && m->next->data<=e)
            m=m->next;
        if (m->data!=e)
        {
            temp->next=m->next;
            m->next=temp;
        }
        else
        {
            if (pr==1)
                printf("Input not unique\n");
            free(temp);
        }
        return first;
    }
}
NODE lunion(NODE l1, NODE l2)
{
    NODE uni=NULL;
    while(l1!=NULL)
    {
        uni=insert(uni,l1->data,0);
        l1=l1->next;
    }
    while(l2!=NULL)
    {
        uni=insert(uni,l2->data,0);
        l2=l2->next;
    }
    return uni;
}
NODE lintersection(NODE l1, NODE l2)
{
    NODE in=NULL;
    while (l1!=NULL)
    {
        NODE pl2=l2;
        while(pl2!=NULL)
        {
            if (l1->data==pl2->data)
            {
                in=insert(in,l1->data,0);
                break;
            }
            pl2=pl2->next;
        }
        l1=l1->next;
    }
    return in;
}
void display(NODE first)
{
    if (first==NULL)
        printf("List Empty\n");
    else
    {
        NODE p=first;
        while (p->next!=NULL)
        {
            printf("%d ",p->data);
            p=p->next;
        }
        printf("%d\n",p->data);
    }
}
