void rimuovi(int a[], int *dim){

  for(int i=0; i<*dim; i++){

    for(int j=i+1; j<*dim; j++){

      if(a[i]==a[j]){

        for(int k=j; k<*dim-1; k++){
          a[k] = a[k+1];
        }

        *dim -=1;


        j--;
      }
    }
  }
}

